<script>
export default {
  name: 'headerPage',
  data: () => ({
    languges: 'ru',
    hoverSocials:{
      instagram: false,
      whatsapp: false,
      telegram: false,
      max: false,
      mail: false,
    }
  }),
  components: {},
  computed: {
    selectLanguage(){
      return this.$store.state.selectLanguage
    }
  },
  methods:{
    runSocial(e){
      const parent = e.target.closest('.img')
      if(parent){
        const social = parent.getAttribute('data')
        switch (social) {
          case 'instagram':
            window.open("https://instagram.com/anissimus?igshid=MzRlODBiNWFlZA==", '_blank').focus()
            // console.log('go to linck 1', social);
            break;
          case 'whatsapp':
            window.open("https://api.whatsapp.com/send/?phone=79183558900", '_blank').focus()
            // console.log('go to linck 2', social);
            break;
          case 'telegram':
            window.open("https://t.me/anissimus", '_blank').focus()
            // console.log('go to linck 3', social);
            break;
          case 'max':
            window.open("https://max.ru/u/f9LHodD0cOJ5MBkBNYPUul-pM1MneHmhmPEhWvrlj4brA8mKte8eDJ4kqwg", '_blank').focus()
            // console.log('go to linck 4', social);
            break;
          case 'mail':
            window.location.href = "mailto:anissimus@mail.ru"
            // console.log('go to linck 5', social);
            break;
          default:
            break;
        }
      }
    },
    changeLanguges(){
      if(this.selectLanguage === 'ru'){
        this.$store.dispatch("changeLanguage", 'en')
      } else {
        this.$store.dispatch("changeLanguage", 'ru')
      }
      localStorage.setItem("language", this.selectLanguage);
    },
    hoverSocial(e){
      if(e.type === 'mouseover'){
        const parent = e.target.closest('.img')
        if(parent){
          const social = parent.getAttribute('data')
          this.hoverSocials[social] = true
        } else {
          Object.entries(this.hoverSocials).map(item => {
          this.hoverSocials[item[0]] = false
        })
        }
      } else {
        Object.entries(this.hoverSocials).map(item => {
          this.hoverSocials[item[0]] = false
        })
      }
    },
  },
  watch:{
  },
  mounted(){
  }
}
</script>

